import {renderResearchResults,renderIntelligenceActions} from './intelligence-ui.js';
const clean=(value,max=500)=>String(value??'').trim().slice(0,max);

export function buildAgentPrompt(question,{connected=false,includeBrief=false,brief={}}={}) {
  const message=clean(question,5000);
  if(!message)throw new Error('Write a question first.');
  const rules=['Work only with private businesses, independent professionals and private-sector career opportunities.','Separate supplied facts from assumptions. Do not invent prospects, buying intent, source checks, conversations or results.','Suggest concrete next steps; do not send messages or change my workspace without asking.'];
  if(connected)rules.unshift('Use my connected Pull GTM MCP tools to read my saved workspace only if useful for this question. Respect the tool permissions and show evidence gaps.');
  else rules.unshift('You do not have access to my Pull GTM workspace. Ask for missing context instead of claiming to have read it.');
  const context=includeBrief?Object.entries({workspace:brief.identity,goal:brief.persona,offer:brief.offer,roles:brief.roles,industries:brief.industries,markets:brief.countries}).map(([key,value])=>[key,clean(value,key==='offer'?500:160)]).filter(([,value])=>value).map(([key,value])=>`${key}: ${value}`).join('\n'):'';
  return `I am using Pull GTM. ${message}\n\n${rules.map((rule,i)=>`${i+1}. ${rule}`).join('\n')}${context?`\n\nMy brief (supplied by me, not independently verified):\n${context}`:''}`;
}

export function localGuidance({mode='empty',items=[],reviewed=0,persona='business'}={}) {
  const counts={fit:items.filter(item=>item.status==='fit').length,review:items.filter(item=>item.status==='review').length,excluded:items.filter(item=>item.status==='excluded').length};
  if(mode==='empty'||!items.length)return {...counts,title:'Start with your own list',detail:persona==='career'?'Import opportunities or contacts you gathered lawfully, then define the roles you want.':'Import a list you own, then define the audience that matters to you.',action:'Import a list',target:'import'};
  if(mode==='example')return {...counts,title:'Explore the method',detail:'These records are fictional. Review a sample to see how Pull separates fit from evidence.',action:'Review examples',target:'prospects'};
  if(counts.review)return {...counts,title:'Close the evidence gaps',detail:`${counts.review} ${counts.review===1?'record needs':'records need'} a closer look before you rely on them.`,action:'Review evidence',target:'prospects'};
  if(counts.fit&&!reviewed)return {...counts,title:'Choose who is worth reaching',detail:`${counts.fit} ${counts.fit===1?'record matches':'records match'} your rules. Check the source and approve each one yourself.`,action:'Review matches',target:'prospects'};
  if(reviewed)return {...counts,title:'Make the next message count',detail:`You reviewed ${reviewed} ${reviewed===1?'prospect':'prospects'}. Prepare a specific, editable message based on verified facts.`,action:'Prepare outreach',target:'drafts'};
  return {...counts,title:'Refine the audience',detail:'Your imported records do not yet match the current rules. Review the criteria and source details.',action:'Adjust audience',target:'prospects'};
}

export function renderWorkflowProposal(message,{escape:e,canApprove=false}={}){
 const p=message.workflow_proposal;if(!p||typeof p!=='object')return '';
 const receipt=message.workflow_result;
 const expired=Date.parse(p.expiresAt)<=Date.now();
 return `<section class="agent-ai-handoff"><span class="section-kicker">${receipt?'WORKFLOW COMPLETED':'YOUR APPROVAL NEEDED'}</span><h3>${e(p.name||'Workflow')}</h3><p>${p.kind==='draft_suggestions'?'Prepare editable drafts for reviewed prospects. Existing drafts stay intact.':'Review audience fit against your saved criteria. No prospects are automatically approved.'} Destination: ${e(p.destination||'none')}. Nothing will be sent.</p>${receipt?`<p role="status">Completed at cloud revision ${e(receipt.revision)}. ${e((receipt.runs||[]).reduce((n,r)=>n+Number(r.counts?.drafts_created||0),0))} draft suggestions created.</p>`:`<button class="button primary" data-action="ai-run-proposal" data-question-id="${e(message.id)}" ${!canApprove||expired?'disabled':''}>Approve and run</button><p class="small-print">${expired?'Expired. Ask for a new proposal.':!canApprove?'Save or load the matching cloud workspace to approve this action.':'Runs once on saved revision '+e(p.revision)+'. Changes require a new proposal.'}</p>`}</section>`;
}

export function renderAgentAIView({cloud,agentState,state,assistantState,items,escape:e,icon}) {
 const active=Boolean(cloud.user&&cloud.verified&&agentState.tokens.some(token=>token.scopes?.includes('chat:relay')));
 const saved=Boolean(cloud.revision>0&&!cloud.dirty);
 const agentMode=assistantState.mode==='agent'&&active;
 const listening=agentMode&&agentState.tokens.some(token=>token.scopes?.includes('chat:relay')&&token.last_chat_poll_at&&Date.now()-Date.parse(token.last_chat_poll_at)<120000);
 const guide=localGuidance({mode:state.mode,items,reviewed:state.shortlist.length,persona:state.persona});
 const prompts=[['Refine my audience','prospects'],['Review the gaps','shield'],['Keep it in my voice','drafts'],['Plan my next move','automations']];
 const messages=agentMode?assistantState.agentMessages||[]:assistantState.messages||[];
 const transcript=messages.length?messages.map((m,messageIndex)=>agentMode?`<article class="ai-message user"><span class="ai-message-label">You</span><p>${e(m.question)}</p></article>${m.status==='answered'&&m.answer?`<article class="ai-message assistant"><span class="ai-message-label">Your agent</span><p>${e(m.answer)}</p></article>`:`<div class="ai-thinking" role="status"><span></span><span></span><span></span>${new Date(m.expires_at)<=new Date()?'Question expired without an answer':m.status==='claimed'?'Your agent is working on this':'Waiting for your agent to check Pull'}</div>`}${renderWorkflowProposal(m,{escape:e,canApprove:saved&&cloud.revision===m.workflow_proposal?.revision&&!assistantState.busy})}`:`<article class="ai-message ${m.role==='assistant'?'assistant':'user'}"><span class="ai-message-label">${m.role==='assistant'?'Pull':'You'}</span><p>${e(m.content)}</p>${m.role==='assistant'?renderResearchResults(m.research,messageIndex,e)+renderIntelligenceActions(m.actions,e):''}</article>`).join(''):`<div class="ai-welcome"><span class="ai-greeting">A CLEARER NEXT MOVE, TOGETHER</span><h2>What would you like to<br><em>work on?</em></h2><p>Talk with Pull about your audience, a business question, or a message. You can start here without connecting another AI app.</p><div class="ai-prompts">${prompts.map(([label,glyph],i)=>`<button data-ai-prompt="${i}"><span class="ai-prompt-icon">${icon(glyph)}</span><strong>${e(label)}</strong>${icon('arrow')}</button>`).join('')}</div><p class="agent-ai-quiet-next">${e(guide.title)}. ${e(guide.detail)} <button class="link-button" ${guide.target==='import'?'data-action="import"':`data-view="${e(guide.target)}"`}>${e(guide.action)} ↗</button></p></div>`;
 return `<section class="ai-workspace agent-ai-workspace ai-chat-layout">
  <div class="ai-main ${messages.length?'has-messages':'is-empty'}">
   <div class="ai-toolbar"><span class="ai-status ${cloud.user&&assistantState.configured!==false?'ready':''}"><span></span>${e(agentMode?listening?'Your agent is available':'Your agent needs to be running':!cloud.user?'Sign in to chat':assistantState.configured===false?'Pull AI setup needed':'Chat with Pull')}</span><div class="ai-toolbar-actions">${active?`<label class="ai-mode-select">Conversation <select id="ai-conversation-mode"><option value="pull" ${!agentMode?'selected':''}>Pull AI</option><option value="agent" ${agentMode?'selected':''}>My agent</option></select></label>`:''}<button class="link-button" data-view="connect">Connect your AI</button></div></div>
   <div id="ai-transcript" class="ai-transcript agent-ai-chat" role="log" aria-live="polite" aria-label="Conversation with ${agentMode?'your agent':'Pull'}">${transcript}${assistantState.busy?`<div class="ai-thinking" role="status"><span></span><span></span><span></span>${agentMode?'Sending your question…':'Pull is thinking…'}</div>`:''}</div>
   <form id="ai-form" class="ai-composer agent-ai-composer"><label for="ai-message">Ask Pull anything about your business</label><textarea id="ai-message" name="message" rows="3" maxlength="5000" placeholder="What are you working on?">${e(assistantState.draft)}</textarea><div class="ai-composer-bottom"><span>${agentMode?'Your agent can use its own voice and knowledge when it answers.':assistantState.shareContext?'Pull can review your saved workspace when useful.':'Workspace access is off.'}</span><button class="button primary" type="submit" ${assistantState.busy?'disabled':''}>${assistantState.busy?'Thinking…':cloud.user?'Send message':'Sign in to chat'} ${icon('arrow')}</button></div></form>
   ${!agentMode?`<label class="ai-research-choice"><input id="ai-allow-research" type="checkbox" ${assistantState.allowResearch?'checked':''}> Allow live prospect research when I ask <small>Uses your source-search allowance.</small></label>`:''}
   ${assistantState.error?`<div class="agent-ai-error" role="alert">${e(assistantState.error)} ${cloud.user?'<button class="link-button" data-action="ai-probe">Check AI connection</button>':''} ${!cloud.user?'<button class="link-button" data-action="account">Sign in</button>':''}</div>`:''}
   ${agentMode&&!listening?`<div class="agent-ai-relay"><strong>Start your agent when you want its voice here.</strong><p>Pull AI remains available from the conversation selector.</p><button class="link-button" data-action="ai-copy-relay">Copy agent startup instruction</button></div>`:''}
  </div>
  <aside class="ai-context agent-ai-aside">${assistantState.selectedOffer?`<div class="ai-context-business"><span>Selected product · version ${e(assistantState.selectedOffer.version)}</span><strong>${e(assistantState.selectedOffer.fields.product)}</strong><p>${e(assistantState.selectedOffer.fields.location)}</p><p>These saved product details are included in this conversation.</p><button class="link-button" data-action="offer-clear">Clear selected product</button></div>`:''}<div class="ai-context-head"><span class="section-kicker">WORKING WITH YOU</span><h3>Your context</h3>${icon('shield')}</div><div class="ai-context-business"><span>${state.context==='company'?'Company workspace':'Personal workspace'}</span><strong>${e(state.identity)}</strong><p>${state.offer?e(state.offer):'Add your offer so Pull understands who you help.'}</p><button class="link-button" data-action="workspace">Edit your brief</button></div><dl class="ai-context-details"><div><dt>Market</dt><dd>${e(state.rules.countries||'Worldwide')}</dd></div><div><dt>Audience</dt><dd>${e(state.rules.roles||'Not set')}</dd></div><div><dt>Reviewed prospects</dt><dd>${state.shortlist.length}</dd></div></dl><label class="ai-context-choice"><input id="ai-share-context" type="checkbox" ${assistantState.shareContext?'checked':''}><span>Use my workspace context</span></label><p class="ai-context-note">Pull shares the brief and up to eight reviewed prospects with the model when selected. Access keys and stored contact fields are excluded. Source excerpts may contain public contact information. Live research uses your source allowance when enabled. Results are added only when you choose. Replies do not send outreach.</p><div class="agent-ai-access"><span class="badge ${active?'fit':'review'}">${active?'Your agent is optional':'Your AI is optional'}</span><p>${active?'Switch to My agent when you want your connected assistant to answer in its own voice.':'Connect Claude Code, Cursor, Codex, or another compatible assistant when you want it to use Pull tools.'}</p><button class="link-button" data-view="connect">Set up your agent ↗</button></div><div class="ai-principle">${icon('shield')}<p>AI suggests.<br><strong>You decide.</strong><small>Evidence and permission still matter.</small></p></div></aside>
 </section>`;
}
